import React, { forwardRef } from 'react';
import styled, { CSSObject } from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';
import {
  SuccessIcon,
  CriticalIcon,
  InformationIcon,
  WarningIcon,
} from '@dynatrace/strato-icons';

import { _useInformationOverlayContext } from './hooks/useInformationOverlayContext.js';
import {
  useFocusRing,
  CSSFocusStylesObject,
} from '../../core/hooks/useFocusRing.js';
import { _useId } from '../../core/hooks/useId.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { RoleVariantType } from '../../core/types/role-variant.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';

//#region Typings
export interface InformationOverlayTriggerProps extends DOMProps, WithChildren {
  /** Optional aria-label to provide an additional description for the trigger. */
  'aria-label'?: string;
}
//#endregion Typings

// #region StyledComponents
const StyledTriggerButton = /* @__PURE__ */ styled('button')<{
  $focusStyle?: CSSFocusStylesObject;
  $isFocusVisible?: boolean;
  $variant?: RoleVariantType;
  $iconOnly?: boolean;
}>(({ $focusStyle, $isFocusVisible, $variant, $iconOnly }) => {
  const iconBaseStyles = {
    flexShrink: 0,
    borderRadius: Borders.Radius.Field.Subdued,
    transition: `background-color ${Animations.Hover.Duration.Base} ${Animations.Hover.Easing}`,
  };

  const baseStyles = {
    backgroundColor: 'transparent',
    padding: Spacings.Size0,
    border: Spacings.Size0,
    display: 'flex',
    alignItems: 'flex-start',
    gap: Spacings.Size2,
    cursor: 'pointer',

    '&:hover': {
      backgroundColor: 'transparent',
    },

    '&:focus-visible': {
      outline: 'none',
    },

    '& > .button-children': {
      whiteSpace: 'initial',
      overflow: 'hidden',
      textOverflow: 'initial',
    },
  };

  const textStyles: CSSObject = {
    '& > span': {
      color: Colors.Text.Neutral.Default,
      fontFamily: Typography.Text.Base.Default.Family,
      fontSize: Typography.Text.Base.Default.Size,
      fontWeight: Typography.Text.Base.Default.Weight,
      lineHeight: Typography.Text.Base.Default.LineHeight,
      textAlign: 'left',
      textDecoration: 'underline',
      textDecorationStyle: 'dashed',
      textUnderlineOffset: Spacings.Size4,
      textDecorationThickness: Borders.Width.Default,
      textDecorationColor: Colors.Border.Neutral.Accent,
      position: 'relative',
      paddingLeft: Spacings.Size2,
      paddingRight: Spacings.Size2,
      borderRadius: Borders.Radius.Field.Subdued,
      transition: `background-color ${Animations.Hover.Duration.Base} ${Animations.Hover.Easing}`,
      ...$focusStyle,
      ...($isFocusVisible && {
        textDecoration: 'none',
      }),
    },
    '&:hover > span': {
      backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
    },
  };

  let iconStyles: CSSObject = {
    '& > svg': {
      color: Colors.Icon.Neutral.Subdued,
      ...iconBaseStyles,
      ...($iconOnly && $focusStyle),
    },
  };

  // if there is no text specified for the trigger, the icon itself receives hover styling
  let iconHoverStyles: CSSObject = {
    '&:hover > svg': {
      backgroundColor: Colors.Background.Field.Neutral.DefaultActive,
    },
  };

  switch ($variant) {
    case 'primary':
      iconStyles = {
        '& > svg': {
          color: Colors.Icon.Primary.Default,
          ...iconBaseStyles,
          ...($iconOnly && $focusStyle),
        },
      };
      iconHoverStyles = {
        '&:hover > svg': {
          backgroundColor: Colors.Background.Field.Primary.DefaultHover,
        },
      };
      break;
    case 'success':
      iconStyles = {
        '& > svg': {
          color: Colors.Icon.Success.Default,
          ...iconBaseStyles,
          ...($iconOnly && $focusStyle),
        },
      };
      iconHoverStyles = {
        '&:hover > svg': {
          backgroundColor: Colors.Background.Field.Success.DefaultActive,
        },
      };
      break;
    case 'warning':
      iconStyles = {
        '& > svg': {
          color: Colors.Icon.Warning.Default,
          ...iconBaseStyles,
          ...($iconOnly && $focusStyle),
        },
      };
      iconHoverStyles = {
        '&:hover > svg': {
          backgroundColor: Colors.Background.Field.Warning.DefaultHover,
        },
      };
      break;
    case 'critical':
      iconStyles = {
        '& > svg': {
          color: Colors.Icon.Critical.Default,
          ...iconBaseStyles,
          ...($iconOnly && $focusStyle),
        },
      };
      iconHoverStyles = {
        '&:hover > svg': {
          backgroundColor: Colors.Background.Field.Critical.DefaultHover,
        },
      };
      break;
  }

  return {
    ...baseStyles,
    ...iconStyles,
    ...($iconOnly ? iconHoverStyles : textStyles),
  } as CSSObject;
});
// #endregion

/**
 * InformationOverlay Trigger component, used for rendering trigger content.
 */
export const Trigger = /* @__PURE__ */ forwardRef<
  HTMLButtonElement,
  InformationOverlayTriggerProps
>((props, forwardedRef) => {
  const {
    children,
    'aria-label': ariaLabel = 'Open additional information.',
    id: propId,
  } = props;
  const { variant, overlayTriggerProps } = _useInformationOverlayContext();
  const id = _useId({ prefix: 'information-overlay-trigger' });

  const { focusProps, focusStyles, isFocusVisible } = useFocusRing({
    variant: children ? 'neutral' : variant,
    isMinimal: true,
  });

  let icon = <InformationIcon />;

  switch (variant) {
    case 'success':
      icon = <SuccessIcon />;
      break;
    case 'warning':
      icon = <WarningIcon />;
      break;
    case 'critical':
      icon = <CriticalIcon />;
      break;
  }

  return (
    <StyledTriggerButton
      ref={forwardedRef}
      $focusStyle={focusStyles}
      $isFocusVisible={isFocusVisible}
      $iconOnly={!children}
      $variant={variant}
      aria-haspopup="dialog"
      aria-label={ariaLabel}
      id={propId ?? id}
      {..._mergeProps(overlayTriggerProps, focusProps)}
    >
      {icon}
      {children && <span>{children}</span>}
    </StyledTriggerButton>
  );
});

(Trigger as typeof Trigger & { displayName: string }).displayName =
  'InformationOverlay.Trigger';
